// The one avatar: a cut-out puppet made from the player's illustration (Chunk C2),
// used in the drills now and on the home screen / player card later.
//
// - The art is cut into pieces (head, torso with shorts, upper arms, forearms,
//   hands, thighs, shins, feet), one image each in assets/avatar/. Pivots and
//   rest angles live in puppetRig.js, generated by the cutting script.
// - Joints: each piece is a <g data-j="..."> placed by poseAvatar() around its
//   pivot. Inside it, the image is turned back by its rest angle, so the
//   posing math works as if every bone were drawn straight down (+y).
// - Sides: "L" / "R" mean the screen side in the unflipped art (front view,
//   so "L" is the character's right hand). The drill engine flips the whole rig
//   with one transform for mirror vs. true view; the jersey number counter-flips.
// - The art has no jersey number; it is drawn live in --jersey-trim.
//
// Coordinates: the rig is drawn around x = 0 (center line) with y in the drill
// box's 0–300 space (floor at y = 258). The caller positions it with a transform.

import { PIECES, ART_BODY, THUMB, RECOLOR_REFS } from "./puppetRig.js";
import { recolorImage, teamColors } from "./recolor.js";
import { jerseyNumberSVG } from "./jerseyNumber.js";

// Kept for callers that pass a look; the puppet has one look (the art).
export const DEFAULT_LOOK = {};

export const BODY = {
  ...ART_BODY,
  ankleX: 35,               // feet about shoulder width (the art stands a bit wider)
  handReach: 13.5,          // wrist -> middle of the hand (free arm)
  // wrist -> fingertips of the dribbling hand, measured on the art: length, and
  // angle offset from the hand's own direction. The fingertips do the work.
  fingertip: { len: 22.2, off: -9.4 },
  // Reach lengths for a dribbling arm. The art shows the arm angled toward the
  // camera, so its forearm (and a little of the upper arm) is foreshortened;
  // pointing down, it is longer on screen. The image stretches to match.
  reachUpper: ART_BODY.upperArm * 1.05,
  reachFore: ART_BODY.forearm * 1.22,   // a kid's forearm is ~0.8 of the upper arm; the art's is 0.68
  stanceHipY: ART_BODY.pelvisY,
};

const ASSET = (name) => new URL(`../../assets/avatar/${name}.webp`, import.meta.url).href;

function piece(name) {
  const p = PIECES[name];
  const turn = p.rest ? ` transform="rotate(${-p.rest})"` : "";
  return `<image href="${ASSET(name)}" x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}"${turn} preserveAspectRatio="none"/>`;
}

const SHOULDER_CAP = 9;

function upperArmMarkup(side) {
  const art = piece("upper" + side);
  // Clip the same painted piece twice in its bone coordinates. Only the part
  // below the cap shortens, with a small overlap along the shared edge.
  return `<g data-j="upper${side}">
    <g data-j="upperStretch${side}">
      <svg x="-40" y="${SHOULDER_CAP}" width="80" height="42" viewBox="-40 ${SHOULDER_CAP} 80 42" overflow="hidden">${art}</svg>
    </g>
    <svg x="-40" y="-40" width="80" height="${40 + SHOULDER_CAP + .35}" viewBox="-40 -40 80 ${40 + SHOULDER_CAP + .35}" overflow="hidden">${art}</svg>
  </g>`;
}

// The dribbling hand carries its thumb as a separate joint (pivot at its base),
// both in the art's own hand frame, so the thumb can fold onto the ball.
function dribbleHand(side) {
  const h = PIECES["hand" + side], t = PIECES["thumb" + side];
  if (!t) return piece("hand" + side);
  const img = (name, p) => `<image href="${ASSET(name)}" x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}" preserveAspectRatio="none"/>`;
  return `<g transform="rotate(${-h.rest})">
      ${img("hand" + side, h)}
      <g data-j="thumb${side}" transform="translate(${THUMB.pivot[0]},${THUMB.pivot[1]})">${img("thumb" + side, t)}</g>
    </g>`;
}

function numberMarkup(number) {
  // Same block digits as the player card; centered on the chest so the mirror-view
  // counter-flip (setNumberFlip) keeps it readable.
  return `<g class="av-num" transform="translate(${NUM.x},${NUM.y})">${jerseyNumberSVG(number, { cx: 0, cy: 0, height: 15, maxWidth: 19 })}</g>`;
}
const NUM = { x: 1.5, y: -34 };   // chest center, relative to the pelvis

/**
 * SVG markup for the rigged avatar (no <svg> wrapper).
 * opts.dribbleSide: "L" | "R" — whose arm goes in front of the ball.
 * opts.slot: markup placed between the free arm and the dribbling arm
 *            (the ball goes here so the dribbling hand sits on top of it).
 * opts.blendArm: preserve the shoulder cap and underpaint the elbow on high catches.
 */
export function avatarMarkup({ number = "", dribbleSide = "L", slot = "", blendArm = false } = {}) {
  const j = (key) => `<g data-j="${key}">${piece(key)}</g>`;
  const free = dribbleSide === "L" ? "R" : "L";
  const upper = (side) => blendArm && side === dribbleSide ? upperArmMarkup(side) : j("upper" + side);
  return `
    <g class="av">
      ${j("head")}${j("hair")}${blendArm ? `<ellipse data-j="elbow${dribbleSide}" cx="-2" cy="1.1" rx="6.2" ry="4.8" fill="#dc9878"/>` : ""}
      ${upper("L")}${upper("R")}
      ${j("thighL")}${j("thighR")}
      ${j("shinL")}${j("shinR")}
      ${j("footL")}${j("footR")}
      <g data-j="torso">${piece("torso")}${numberMarkup(number)}</g>
      ${j("fore" + free)}${j("hand" + free)}
      ${slot}
      ${j("fore" + dribbleSide)}<g data-j="hand${dribbleSide}">${dribbleHand(dribbleSide)}</g>
    </g>`;
}

/**
 * Paint the jersey, shorts and trim in the team colors (from the player card).
 * Async the first time for a color pair, then cached. Returns a promise.
 */
export function applyTeamColors(svgRoot, colors = teamColors()) {
  const jobs = Object.keys(RECOLOR_REFS).map((name) => {
    const img = svgRoot.querySelector(`[data-j="${name}"] > image`);
    if (!img) return null;
    return recolorImage(ASSET(name), ASSET(`${name}_mask`), colors.jersey, colors.trim, RECOLOR_REFS[name])
      .then((url) => { if (img.isConnected) img.setAttribute("href", url); })
      .catch(() => {});                               // keep the original art if anything fails
  });
  return Promise.all(jobs);
}

/** Collect the joint groups once, so posing each frame is cheap. */
export function rigRefs(svgRoot) {
  const refs = {};
  svgRoot.querySelectorAll("[data-j]").forEach((el) => { refs[el.dataset.j] = el; });
  refs.num = svgRoot.querySelector(".av-num");
  return refs;
}

// ---------- posing ----------
const DEG = 180 / Math.PI;
const r2 = (n) => Math.round(n * 100) / 100;
// Rotation (deg) that points a segment drawn along +y in direction (dx, dy).
const segAngle = (dx, dy) => Math.atan2(-dx, dy) * DEG;

// Two-bone IK. bend = +1 puts the elbow/knee toward -x (screen left), -1 toward +x.
export function solveTwoBone(sx, sy, tx, ty, l1, l2, bend) {
  const dx = tx - sx, dy = ty - sy;
  const d = Math.min(Math.max(Math.hypot(dx, dy), Math.abs(l1 - l2) + 0.01), l1 + l2 - 0.01);
  const base = Math.atan2(dy, dx);
  const a = Math.acos((l1 * l1 + d * d - l2 * l2) / (2 * l1 * d));
  const ex = sx + l1 * Math.cos(base + bend * a);
  const ey = sy + l1 * Math.sin(base + bend * a);
  const upper = segAngle(ex - sx, ey - sy);
  const lower = segAngle(tx - ex, ty - ey);
  return { upper, lower: lower - upper, elbow: { x: ex, y: ey } };
}

/**
 * Place every joint for one frame.
 * pose = {
 *   hipY,                 // pelvis height (stance = BODY.stanceHipY; lower = deeper knees)
 *   headY,                // optional head pivot override (head steadier than torso)
 *   lean,                 // optional torso tilt in degrees around the pelvis (- = screen-left shoulder down)
 *   hinge,                // optional forward lean at the hips, as a fraction the torso shortens on screen
 *   headLift,             // optional: how much the head rides up against the bob (head steadier than torso)
 *   hair,                 // optional: hair's trailing offset from the head (secondary motion, + = down)
 *   cloth,                // optional: tiny jersey settle, as extra torso stretch (secondary motion)
 *   arms: { L: { target: {x,y}, hand, ball: {x,y,r}, grip } | { upper, fore, hand }, R: ... },
 *     (ball + grip: the thumb folds so its tip rests on the ball; grip 0..1 blends it in)
 *     (armGuide: optional projected elbow offsets and hand angle for a high receive)
 *   knees: outward knee offset in rig units (bent knees read as slightly out in front view)
 * }
 * Targets are the finger contact point in rig space (x around 0, y in the 0–300 box).
 */
export function poseAvatar(refs, pose) {
  const B = BODY;
  const hipY = pose.hipY ?? B.stanceHipY;
  const lean = pose.lean ?? 0;
  const ts = 1 - (pose.hinge ?? 0) + (pose.cloth ?? 0);
  const set = (key, t) => refs[key]?.setAttribute("transform", t);
  const lr = lean / DEG;
  // A point fixed to the torso (relative to the pelvis), after the lean.
  const onTorso = (x, y) => ({
    x: x * Math.cos(lr) - y * ts * Math.sin(lr),
    y: hipY + x * Math.sin(lr) + y * ts * Math.cos(lr),
  });

  set("torso", `translate(0,${r2(hipY)}) rotate(${r2(lean)}) scale(1,${r2(ts * 1000) / 1000})`);
  const neck = onTorso(B.neckX, B.neckTop);
  const headY = neck.y - (pose.headLift ?? 0);
  set("head", `translate(${r2(neck.x)},${r2(headY)}) rotate(${r2(lean * 0.25)})`);
  set("hair", `translate(${r2(neck.x)},${r2(headY + (pose.hair ?? 0))}) rotate(${r2(lean * 0.25)})`);

  // Legs: feet planted; knees placed between hip and ankle, nudged outward.
  // Segment lengths are fitted with scaleY (front-view foreshortening).
  for (const s of ["L", "R"]) {
    const sign = s === "L" ? -1 : 1;
    const hip = onTorso(sign * B.hipX, B.hipDrop);
    const hx = hip.x, hy = hip.y;
    const ax = sign * B.ankleX, ay = B.ankleY;
    const kx = hx + (ax - hx) * B.kneeT + sign * (pose.knees ?? 0);
    const ky = hy + (ay - hy) * B.kneeT;
    set(`thigh${s}`, `translate(${r2(hx)},${r2(hy)}) rotate(${r2(segAngle(kx - hx, ky - hy))}) scale(1,${r2(Math.hypot(kx - hx, ky - hy) / B.thigh)})`);
    set(`shin${s}`, `translate(${r2(kx)},${r2(ky)}) rotate(${r2(segAngle(ax - kx, ay - ky))}) scale(1,${r2(Math.hypot(ax - kx, ay - ky) / B.shin)})`);
    set(`foot${s}`, `translate(${ax},${ay})`);
  }

  // Arms. In a front view a bent elbow mostly points toward the camera, so the
  // elbow only swings out a little (FORESHORTEN) and the segments get shorter
  // on screen (scaleY). The hand is never scaled, and its contact point lands
  // exactly on the target, so the hand and ball can't drift apart.
  const FORESHORTEN = 0.35;
  for (const s of ["L", "R"]) {
    const a = pose.arms?.[s];
    if (!a) continue;
    const sign = s === "L" ? -1 : 1;
    const sh = onTorso(sign * B.shoulderX, B.shoulderY);
    const sx = sh.x, sy = sh.y;
    const h = a.hand ?? 0;
    const dir = (deg) => ({ x: -Math.sin(deg / DEG), y: Math.cos(deg / DEG) });
    let ex, ey, wx, wy, foreAng;
    if (a.target && a.armGuide) {
      // Guide the elbow below the shoulder during a high receive. With the
      // hand angle set by the motion, solve the wrist directly from the fingers.
      const guide = a.armGuide;
      const d = dir(guide.handAngle + B.fingertip.off);
      wx = a.target.x - d.x * B.fingertip.len;
      wy = a.target.y - d.y * B.fingertip.len;
      ex = sx + sign * guide.out;
      ey = sy + guide.down;
      foreAng = segAngle(wx - ex, wy - ey);
    } else if (a.target) {
      // The fingertips (turned with the wrist) must land exactly on the target,
      // so solve for the wrist: a few damped fixed-point steps.
      const L1 = B.reachUpper, L2 = B.reachFore, FT = B.fingertip;
      const tx = a.target.x, ty = a.target.y;
      foreAng = segAngle(tx - sx, ty - sy);
      for (let i = 0; i < 10; i++) {
        const d = dir(foreAng + h + FT.off);
        wx = tx - d.x * FT.len; wy = ty - d.y * FT.len;
        const sol = solveTwoBone(sx, sy, wx, wy, L1, L2, s === "L" ? 1 : -1);
        const k = L1 / (L1 + L2);
        const mx = sx + (wx - sx) * k, my = sy + (wy - sy) * k;
        ex = mx + (sol.elbow.x - mx) * FORESHORTEN;
        ey = my + (sol.elbow.y - my) * FORESHORTEN;
        foreAng = (foreAng + segAngle(wx - ex, wy - ey)) / 2;   // damped, so it settles
      }
      const d = dir(foreAng + h + FT.off);
      wx = tx - d.x * FT.len; wy = ty - d.y * FT.len;
    } else {
      const L1 = B.upperArm, L2 = B.forearm;
      const u = (a.upper ?? 0) + lean, f = u + (a.fore ?? 0);
      ex = sx + dir(u).x * L1; ey = sy + dir(u).y * L1;
      wx = ex + dir(f).x * L2; wy = ey + dir(f).y * L2;
      foreAng = f;
    }
    const upperAng = segAngle(ex - sx, ey - sy);
    const upperLength = Math.hypot(ex - sx, ey - sy);
    const shoulderPose = `translate(${r2(sx)},${r2(sy)}) rotate(${r2(upperAng)})`;
    // Underpaint the joint where the feathered edges of the two arm pieces meet.
    refs[`elbow${s}`]?.setAttribute("transform", `translate(${r2(ex)},${r2(ey)}) rotate(${r2(upperAng)}) scale(${-sign},1)`);
    if (refs[`upperStretch${s}`]) {
      const stretch = (upperLength - SHOULDER_CAP) / (B.upperArm - SHOULDER_CAP);
      set(`upper${s}`, shoulderPose);
      set(`upperStretch${s}`, `translate(0,${SHOULDER_CAP}) scale(1,${stretch.toFixed(3)}) translate(0,${-SHOULDER_CAP})`);
    } else {
      set(`upper${s}`, `${shoulderPose} scale(1,${r2(upperLength / B.upperArm)})`);
    }
    set(`fore${s}`, `translate(${r2(ex)},${r2(ey)}) rotate(${r2(foreAng)}) scale(1,${r2(Math.hypot(wx - ex, wy - ey) / B.forearm)})`);
    const handAng = a.armGuide?.handAngle ?? foreAng + h;
    set(`hand${s}`, `translate(${r2(wx)},${r2(wy)}) rotate(${r2(handAng)})`);
    if (refs[`thumb${s}`]) set(`thumb${s}`, `translate(${THUMB.pivot[0]},${THUMB.pivot[1]}) rotate(${r2(thumbAngle(a, wx, wy, handAng - PIECES["hand" + s].rest))})`);
  }
}

// Thumb angle (deg, in the hand's art frame) that rests its tip on the ball.
const THUMB_RELAXED = 10;
function thumbAngle(a, wx, wy, handTurn) {
  if (!a.ball) return THUMB_RELAXED;
  const t = handTurn / DEG;
  const dx = a.ball.x - wx, dy = a.ball.y - wy;
  // ball center in the hand's art frame (relative to the thumb's base)
  const cx = dx * Math.cos(t) + dy * Math.sin(t) - THUMB.pivot[0];
  const cy = -dx * Math.sin(t) + dy * Math.cos(t) - THUMB.pivot[1];
  const vx = THUMB.tip[0] - THUMB.pivot[0], vy = THUMB.tip[1] - THUMB.pivot[1];
  const want = a.ball.r - 0.5;                    // pads press just onto the leather
  // The tip's distance to the ball shrinks as the thumb folds toward the fingers;
  // take the first (gentlest) fold that reaches the leather, so the angle never
  // jumps between the two possible solutions.
  const gap = (deg) => {
    const c = Math.cos(deg / DEG), s = Math.sin(deg / DEG);
    return Math.hypot(vx * c - vy * s - cx, vx * s + vy * c - cy) - want;
  };
  // If it can't reach, point it where it comes closest (that meets the first fold
  // smoothly at the moment of contact).
  let best = -15, closest = Infinity;
  for (let d = -15; d <= 85; d += 1) { const g = gap(d); if (g < closest) { closest = g; best = d; } }
  if (gap(-15) <= 0) best = -15;                    // already touching: lift as far as it goes
  else if (closest <= 0) {
    for (let d = -13; d <= 85; d += 2) {
      if (gap(d) <= 0) {                            // bisect between d - 2 and d
        let lo = d - 2, hi = d;
        for (let i = 0; i < 12; i++) { const mid = (lo + hi) / 2; if (gap(mid) > 0) lo = mid; else hi = mid; }
        best = hi; break;
      }
    }
  }
  const g = a.grip ?? 1;
  return THUMB_RELAXED + (best - THUMB_RELAXED) * g;
}

/** Keep the jersey number readable when the rig is flipped. */
export function setNumberFlip(refs, flipped) {
  refs.num?.setAttribute("transform", `translate(${NUM.x},${NUM.y})${flipped ? " scale(-1,1)" : ""}`);
}
